    function stats(s=state){const out={atk:s.player.baseAtk,def:s.player.baseDef,maxHp:s.player.maxHp,maxMana:s.player.maxMana,crit:s.world.shadow ? .04 : 0,drain:0};for(const slot of Object.keys(SLOT)){const it=ITEMS[s.inventory.equip[slot]];if(it)for(const [k,v] of Object.entries(window.GrowthSystem.bonus(s,s.inventory.equip[slot],it))){const key={atk:"atk",def:"def",hp:"maxHp",mana:"maxMana",crit:"crit",drain:"drain"}[k];out[key]+=v}}for(const id of s.learned){const sk=SKILLS[id];if(!sk||sk.job!==s.job)continue;const e=sk.effect,v=sk.value||0;if(e==="guard"){out.def+=2;out.maxHp+=18}else if(e==="mana")out.maxMana+=v||20;else if(e==="atk")out.atk+=v;else if(e==="def")out.def+=v;else if(e==="hp")out.maxHp+=v;else if(e==="crit")out.crit+=v;else if(e==="windrunner"){out.crit+=.04;out.maxHp+=8}else if(e==="fateThread"){out.atk+=2;out.maxMana+=8}else if(e==="guardian"){out.def+=3;out.maxHp+=10}else if(e==="sharedVow")out.maxHp+=12}for(const id of s.party.active){const c=COMPANIONS[id];if(c)for(const [k,v] of Object.entries(c.bonus)){const key={atk:"atk",def:"def",hp:"maxHp",mana:"maxMana",crit:"crit"}[k];if(key)out[key]+=v}}return out}
    function fmtStats(o){return Object.entries(o).map(([k,v])=>({atk:`攻击 +${v}`,def:`防御 +${v}`,hp:`生命 +${v}`,mana:`法力 +${v}`,crit:`暴击 +${Math.round(v*100)}%`,drain:`汲取 +${Math.round(v*100)}%`}[k])).join(" · ")}
