    function completeQuest(s,id){const q=s.quests[id],def=QUESTS[id];if(!def||q.done)return;q.done=true;const resident={stars:"mira",herbs:"pella",roots:"sylvi",caravan:"toren",names:"eira",letters:"lian"}[id];if(resident)window.GrowthSystem.addAffinity(s,resident,10);const r=def.reward;s.player.xp+=r.xp||0;s.player.gold+=r.gold||0;if(r.rep)changeRep(s,r.rep);if(r.item)grantItem(s,r.item,true);appendLog(s,`委托「${def.name}」完成。${def.desc} 奖励已收入行囊。`);levelUp(s)}
