    function explorationProgress(){if(window.CircleMap.progress)return Object.fromEntries(Object.keys(PLACES).map(k=>[k,window.CircleMap.progress(state,k)]));const s=state;return Object.fromEntries(Object.keys(PLACES).map(k=>{const bs=BUILDINGS.at(k),props=bs.flatMap(b=>{const r=BUILDINGS.interior(b.id);return r?(r.props||[]).map(p=>r.occupantKey+":"+p.id):[]}),events=Object.entries(window.RegionContent.events).filter(([,e])=>e.place===k).map(([id])=>id),total=1+bs.length+props.length+events.length+2,found=Number(s.exploration.regions.includes(k))+bs.filter(b=>s.exploration.buildings.includes(b.id)).length+props.filter(p=>s.exploration.props.includes(p)).length+events.filter(e=>s.exploration.events.includes(e)).length+["boss-","elite-"].filter(prefix=>s.exploration.challenges.includes(prefix+k)).length;return[k,Math.floor(found/total*100)];}));}
    function travel(id){if(state.battle){toast("先结束当前战斗。",true);return}if(!PLACES[id]||state.place===id)return;closeModal();window.PixelWorld.clearInput();window.PixelWorld.leaveInterior();transact(s=>{s.place=id;s.location={sceneId:null,...window.WorldRegions.spawn(id),zoom:1,stack:[]};window.GrowthSystem.discover(s,"regions",id);advance(s,2);appendLog(s,"你沿旧路抵达"+PLACES[id].name+"，归灯在身后渐渐远去。");if(id==="wood")unlockQuest(s,"pages");if(id==="fen")unlockQuest(s,"moon");});showScreen("adventure");}
