    function cityService(id){if(state.battle||state.place!=='city'||!window.RoyalCity.services[id.slice(5)])return;const room=window.PixelWorld.getInterior(),available=room?room.service===id||window.NPCSystem.inside(room.occupantKey).some(n=>n.service===id):id==='city:guide'||id==='city:archive'||id==='city:music'||BUILDINGS.at('city').some(b=>b.action===id)||window.NPCSystem.at('city').some(n=>n.service===id);if(!available)return;const info=window.RoyalCity.serviceInfo(state,id);if(!info.available){toast(info.reason,true);return;}if(['guide','archive','music'].includes(info.key)){if(info.key==='guide'){const u=window.GameUI.views.codex||(window.GameUI.views.codex={});u.mapMode='local';u.mapPage=0;}openModal('<span class="eyebrow">归灯王城 · 城市生活</span><h2>'+info.name+'</h2><p>'+(info.key==='guide'?'九个街区由大道与河桥相连，可步行或通过区域地点地图前往。':info.key==='archive'?'王城公开了街坊修桥、重开书院与整理旧门牌的记录。这里记下普通居民的名字，不以功勋和冠冕衡量他们。':'弦音从水镜亭传来：归灯照着窗，河水绕着墙，等到晚风把旧名字送回街坊。')+'</p><div class="modal-actions">'+(info.key==='guide'?'<button class="modal-option" data-screen="codex" data-open-tab="map">打开街区地图</button>':'')+'<button class="modal-option" data-close="1">返回</button></div>');return;}let ok=false;transact(s=>{const error=window.RoyalCity.service(s,id,{stats,log:appendLog,advance});if(error)toast(error,true);else ok=true;});if(ok)toast(info.name+'已完成。');}
    function showRegionEvent(id){const e=window.RegionContent.events[id];if(!e||e.place!==state.place||state.battle)return;if(state.exploration.events.includes(id)){toast("这个事件已记录。");return}openModal('<span class="eyebrow">区域事件</span><h2>'+e.title+'</h2><p>'+e.body+'</p><div class="modal-actions">'+e.options.map((o,i)=>'<button class="modal-option" data-region-option="'+i+'" data-region-id="'+id+'"><b>'+o.name+'</b><small>'+o.desc+'</small></button>').join('')+'<button class="modal-option" data-close="1">稍后决定</button></div>');}
    function chooseRegionEvent(id,index){const e=window.RegionContent.events[id],o=e?.options[index];if(!e||!o||e.place!==state.place||state.battle||state.exploration.events.includes(id))return;let ok=false;transact(s=>{if(o.mp&&s.player.mana<o.mp){toast("法力不足。",true);return}if(Object.entries(o.cost||{}).some(([k,n])=>s.inventory.materials[k]<n)){toast("材料不足。",true);return}for(const[k,n]of Object.entries(o.cost||{}))s.inventory.materials[k]-=n;s.player.mana-=o.mp||0;s.player.gold+=o.gold||0;s.supplies+=o.supplies||0;for(const[k,n]of Object.entries(o.materials||{}))s.inventory.materials[k]+=n;for(const[k,n]of Object.entries(o.world||{}))s.world[k]+=n;if(o.affinity)window.GrowthSystem.addAffinity(s,...o.affinity);window.GrowthSystem.discover(s,"events",id);s.flags["event:"+id]=index;appendLog(s,e.title+"："+o.text);advance(s);ok=true;});if(ok)closeModal();}
